<script setup lang="ts">
import { ref, computed } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowUpRight, Download, Copy, Check } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import { contact, catalogUrl, whatsappUrl } from '../data/site'
import { plans } from '../data/pricing'
const route=useRoute()
const name=ref(''), phone=ref(''), business=ref(''), city=ref(''), industry=ref('Digital Printing'), notes=ref('')
const chosen=String(route.query.paket||'')
const plan=ref(plans.some(p=>p.name===chosen)?chosen:'Belum tahu, ingin konsultasi')
const prepared=ref(false), copied=ref(false), copyError=ref(false)
const message=computed(()=>`Halo Grafika Pro, saya ingin berkonsultasi dan menjadwalkan demo.\n\nNama: ${name.value}\nWhatsApp: ${phone.value}\nNama usaha: ${business.value || '-'}\nKota: ${city.value || '-'}\nJenis usaha: ${industry.value}\nPaket: ${plan.value}\n\nKebutuhan: ${notes.value || 'Ingin mengenal Grafika Pro dan menemukan paket yang sesuai.'}`)
const link=computed(()=>whatsappUrl(message.value))
function prepare(){prepared.value=true;copied.value=false;copyError.value=false}
async function copy(){try{await navigator.clipboard.writeText(message.value);copied.value=true;copyError.value=false}catch{copyError.value=true}}
</script>
<template><PageHeading label="KONSULTASI & DEMO" number="06 / MARI MULAI" title="Ceritakan percetakan Anda." accent="Kita mulai dari sana." description="Apa yang paling sering menghambat pekerjaan sehari-hari? Siapkan kebutuhan Anda agar konsultasi lebih terarah."/><div class="contact-grid wrap"><form class="contact-form" @submit.prevent="prepare"><div class="field-grid"><label class="field">Nama Anda *<input v-model="name" name="name" autocomplete="name" required maxlength="100" placeholder="Nama lengkap"/></label><label class="field">Nomor WhatsApp *<input v-model="phone" name="tel" autocomplete="tel" type="tel" required pattern="[+0-9 ()-]{8,20}" title="Masukkan nomor telepon 8–20 karakter, misalnya 081234567890" maxlength="20" placeholder="08xxxxxxxxxx"/></label></div><div class="field-grid"><label class="field">Nama usaha<input v-model="business" name="organization" autocomplete="organization" maxlength="150" placeholder="Nama percetakan Anda"/></label><label class="field">Kota<input v-model="city" name="city" autocomplete="address-level2" maxlength="100" placeholder="Kota usaha"/></label></div><div class="field-grid"><label class="field">Jenis usaha<select v-model="industry"><option>Digital Printing</option><option>Offset Printing</option><option>Advertising</option><option>Sablon</option><option>Fotokopi & Print Shop</option><option>Lainnya</option></select></label><label class="field">Paket yang diminati<select v-model="plan"><option>Belum tahu, ingin konsultasi</option><option v-for="p in plans" :key="p.name" :value="p.name">{{p.name}}</option></select></label></div><label class="field">Apa yang ingin dibantu?<textarea v-model="notes" maxlength="2000" placeholder="Contoh: status produksi masih di grup chat, stok sering selisih, atau ingin memahami HPP setiap order."></textarea></label><button class="button" type="submit">Siapkan Pesan Konsultasi <ArrowUpRight :size="18"/></button><p class="form-note">Data di formulir ini hanya dipakai untuk menyusun pesan di perangkat Anda. Tidak otomatis dikirim atau disimpan di server.</p><section v-if="prepared" class="contact-status" aria-live="polite"><strong>Pesan konsultasi siap.</strong><pre class="message-preview">{{message}}</pre><div class="actions"><a v-if="link" :href="link" target="_blank" rel="noopener" class="button">Lanjut ke WhatsApp <ArrowUpRight :size="17"/></a><button type="button" class="button secondary" @click="copy"><Check v-if="copied" :size="16"/><Copy v-else :size="16"/>{{copied?'Pesan tersalin':'Salin pesan'}}</button></div><p v-if="!link" class="form-note" style="margin-bottom:0">Kontak konsultasi belum dicantumkan di website. Anda dapat menyimpan pesan ini untuk dibagikan kepada tim Grafika Pro melalui kontak yang Anda miliki.</p><p v-if="copyError" role="alert">Pesan belum dapat disalin otomatis. Pilih teks pesan di atas, lalu salin secara manual.</p></section></form><aside class="contact-aside"><p class="eyebrow">MAKE IT EASY</p><h2>Bukan cuma memilih<br/>software.</h2><p>Kita membahas cara kerja, kesiapan tim, dan kebutuhan data. Supaya sistem yang dipilih benar-benar membantu operasional.</p><ul class="check-list"><li>Diskusi kebutuhan dan alur kerja</li><li>Pengenalan modul yang relevan</li><li>Penjelasan paket dan biaya awal</li></ul><a :href="catalogUrl" target="_blank" rel="noopener" class="text-link">Pelajari katalog terlebih dahulu <Download :size="17"/></a><a v-if="contact.email" :href="'mailto:'+contact.email" class="text-link">{{contact.email}} <ArrowUpRight :size="17"/></a><p v-if="!contact.whatsapp" class="form-note" style="margin-top:25px;margin-bottom:0">Informasi kontak resmi akan dilengkapi. Sementara itu, seluruh modul dan rincian harga tersedia di katalog.</p></aside></div></template>
